<script setup>
function displayPhone(v){return String(v||'').replace(/^\+86(?=1\d{10}$)/,'')}

import {ask} from './ui'
import CredentialsPanel from './CredentialsPanel.vue'
import {ref,computed,onMounted,onUnmounted} from 'vue'
const props=defineProps({api:Function,section:{type:String,default:'users'}})
const users=ref([]),numbers=ref([]),error=ref(''),notice=ref(''),busy=ref(false),tab=ref(props.section==='recycle'?'numbers':'users'),showDeleted=ref(props.section==='recycle'),owners=ref({}),creating=ref(false)
const search=ref('')
const matchedUsers=computed(()=>users.value.filter(u=>u.username.toLowerCase().includes(search.value.trim().toLowerCase())))
const form=ref({username:'',password:''})
let timer
async function load(){try{const d=await props.api('/admin/overview');users.value=d.users;numbers.value=d.numbers;for(const n of d.numbers)if(!(n.id in owners.value))owners.value[n.id]=n.owner_id}catch(e){error.value=e.message}}
async function action(path,method,body){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await props.api(path,{method,...(body?{body:JSON.stringify(body)}:{})});notice.value='操作已保存';await load();return true}catch(e){error.value=e.message;return false}finally{busy.value=false}}
async function create(){if(await action('/admin/users','POST',form.value)){form.value={username:'',password:''};creating.value=false}}
async function remove(n){if(!await ask(`删除 ${n.number}？系统将停止接收，保留历史记录，可在回收站恢复。`))return;await action('/numbers/'+n.id,'DELETE')}
async function assign(n){if(!await ask('更改归属后，该号码的历史短信和来电也将对新用户可见。确定分配？'))return;await action('/admin/numbers/'+n.id+'/owner','PUT',{user_id:Number(owners.value[n.id])})}
onMounted(()=>{load();timer=setInterval(load,15000)})
onUnmounted(()=>{clearInterval(timer);form.value.password=''})
</script>
<template>
 <div class="admin-metrics"><article><span>用户</span><strong>{{users.filter(u=>u.role==='user').length}}</strong></article><article><span>管理号码</span><strong>{{numbers.filter(n=>!n.deleted).length}}</strong></article><article><span>接收器存活</span><strong>{{numbers.filter(n=>!n.deleted&&n.receiver?.state==='online').length}}</strong></article><article><span>回收站</span><strong>{{numbers.filter(n=>n.deleted).length}}</strong></article></div>
 <p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="notice" class="admin-notice" role="status">{{notice}}</p>
 <section class="simple-panel admin-panel"><header class="simple-panel-title"><div v-if="section!=='recycle'" class="tabs"><button :class="{active:tab==='users'}" @click="tab='users'">用户管理</button><button :class="{active:tab==='numbers'}" @click="tab='numbers'">号码分配</button></div><h3 v-else>回收站</h3><button v-if="tab==='users'" class="button primary" @click="creating=true">创建用户</button><button v-else-if="section!=='recycle'" class="button" @click="showDeleted=!showDeleted">{{showDeleted?'返回正常号码':'回收站'}}</button></header>
 <p class="admin-hint">{{tab==='users'?'普通用户仅可访问其归属号码、消息及转发渠道；停用会立即撤销登录会话。':'分配号码会同时转移历史记录的访问权限。恢复号码不会自动启动接收。'}}</p>
 <template v-if="tab==='users'"><input v-model="search" class="admin-search" placeholder="搜索用户名" aria-label="搜索用户"><div v-for="u in matchedUsers" :key="u.id" class="admin-row"><div><strong>{{u.username}}</strong><small>{{u.role==='admin'?'管理员':'普通用户'}} · {{u.numbers}} 个号码 · {{u.disabled?'已停用':'可登录'}}</small></div><button v-if="u.role!=='admin'" class="button" :disabled="busy" @click="action('/admin/users/'+u.id,'PATCH',{disabled:!u.disabled})">{{u.disabled?'启用':'停用'}}</button><span v-else class="admin-hint">系统管理员</span></div></template>
 <template v-else><div v-for="n in numbers.filter(n=>n.deleted===showDeleted)" :key="n.id" class="admin-row"><div><strong>{{displayPhone(n.number)}}</strong><small>{{n.label||'未设置备注'}} · {{n.username||'未分配'}} · {{n.deleted?'已删除（停止接收：'+(n.delete_state==='done'?'完成':n.delete_state==='failed'?'失败，请重试':n.delete_state||'未知')+'）':n.receiver?.state==='online'?'接收器存活':'接收器未连接'}}</small></div><template v-if="!n.deleted"><CredentialsPanel :api="api" :id="n.id"/><select v-model="owners[n.id]" aria-label="号码所属用户"><option v-for="u in users.filter(u=>!u.disabled)" :key="u.id" :value="u.id">{{u.username}}</option></select><button class="button" :disabled="busy||Number(owners[n.id])===n.owner_id" @click="assign(n)">分配</button><button class="text-button danger" :disabled="busy" @click="remove(n)">删除</button></template><template v-else><button v-if="n.delete_state==='failed'" class="button" :disabled="busy" @click="remove(n)">重试停止</button><button class="button" :disabled="busy||n.delete_state==='queued'||n.delete_state==='running'" @click="action('/admin/numbers/'+n.id+'/restore','POST')">恢复号码</button></template></div><div v-if="!numbers.some(n=>n.deleted===showDeleted)" class="empty-state"><p>{{showDeleted?'回收站为空':'暂无号码'}}</p></div></template></section>
 <div v-if="creating" class="admin-overlay" @click.self="!busy&&(creating=false)"><section class="admin-dialog" role="dialog" aria-modal="true" aria-label="创建用户"><h3>创建用户</h3><form @submit.prevent="create"><label>用户名<input v-model="form.username" required minlength="2" maxlength="64" pattern="[A-Za-z0-9_.\-]+" autocomplete="off" placeholder="字母、数字、点、横线或下划线"></label><label>登录密码<input v-model="form.password" required minlength="6" maxlength="128" type="password" autocomplete="new-password" placeholder="至少 6 位，允许纯数字"></label><p v-if="error" class="danger" role="alert">{{error}}</p><footer><button type="button" class="button" :disabled="busy" @click="creating=false;form.password=''">取消</button><button class="button primary" :disabled="busy">{{busy?'正在保存…':'创建用户'}}</button></footer></form></section></div>
</template>
<style scoped>
.admin-metrics{display:grid;grid-template-columns:repeat(4,1fr);background:white;border:1px solid #e5e8ed;border-radius:14px;margin-bottom:22px;padding:22px 0}.admin-metrics article{padding:0 24px;display:grid;gap:12px}.admin-metrics article+article{border-left:1px solid #eceef1}.admin-metrics span{font-size:12px;color:#88919d}.admin-metrics strong{font-size:30px;font-weight:550}.admin-hint{font-size:12px;color:#9299a4;line-height:1.8;padding:14px 22px}.admin-row{padding:18px 22px;display:flex;gap:12px;align-items:center;border-top:1px solid #eef0f3}.admin-row>div{flex:1;min-width:0}.admin-row strong{font-size:13px;font-weight:550}.admin-row small{display:block;font-size:11px;color:#9099a6;margin-top:7px;overflow-wrap:anywhere}.admin-row select{max-width:160px;padding:8px;border:1px solid #e1e5eb;border-radius:8px;background:#fff}.admin-notice{color:#388461;font-size:13px;margin:12px 0}.danger{color:#b94a4a}.admin-overlay{position:fixed;inset:0;background:#1d24356b;z-index:100;display:grid;place-items:center;padding:20px}.admin-dialog{width:min(440px,100%);background:white;border-radius:16px;padding:28px;max-height:90dvh;overflow:auto}.admin-dialog h3{margin-bottom:20px}.admin-dialog label{display:grid;gap:9px;margin:18px 0;font-size:13px}.admin-dialog input{padding:12px;border:1px solid #dfe4eb;border-radius:8px;width:100%;box-sizing:border-box;font:inherit}.admin-dialog footer{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}@media(max-width:760px){.admin-metrics{grid-template-columns:repeat(2,1fr);gap:22px 0}.admin-metrics article:nth-child(3){border-left:0}.admin-row{flex-wrap:wrap}.admin-row>div{flex-basis:100%}.admin-row select{flex:1;max-width:none}}
</style>
